  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter)
  }

  /** helper function to set the values of all input ports.
   * @param airCarePreference payload for data port airCarePreference
   * @param preferenceValidity payload for data port preferenceValidity
   */
  def put_concrete_inputs(airCarePreference : Cabin_Air_Care_Supervisor.AirCarePreference.Type,
                          preferenceValidity : Cabin_Air_Care_Supervisor.PreferenceValidity.Type): Unit = {
    put_airCarePreference(airCarePreference)
    put_preferenceValidity(preferenceValidity)
  }


  /** helper function to check PreferenceInterpreter_airCareSupervisionProcess_preferenceInterpreter's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param airCareIntent method that will be called with the value of the outgoing data
   *        port 'airCareIntent'.
   */
  def check_concrete_output(airCareIntent: Cabin_Air_Care_Supervisor.AirCareIntent.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val airCareIntentValue: Cabin_Air_Care_Supervisor.AirCareIntent.Type = get_airCareIntent().get
    if(!airCareIntent(airCareIntentValue)) {
      testFailures = testFailures :+ st"'airCareIntent' did not match expected: value of the outgoing data port is ${airCareIntentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_airCarePreference(value : Cabin_Air_Care_Supervisor.AirCarePreference.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter.operational_api.airCarePreference_Id, Cabin_Air_Care_Supervisor.AirCarePreference_Payload(value))
  }

  // setter for in DataPort
  def put_preferenceValidity(value : Cabin_Air_Care_Supervisor.PreferenceValidity.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter.operational_api.preferenceValidity_Id, Cabin_Air_Care_Supervisor.PreferenceValidity_Payload(value))
  }

  // getter for out DataPort
  def get_airCareIntent(): Option[Cabin_Air_Care_Supervisor.AirCareIntent.Type] = {
    val value: Option[Cabin_Air_Care_Supervisor.AirCareIntent.Type] = get_airCareIntent_payload() match {
      case Some(Cabin_Air_Care_Supervisor.AirCareIntent_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port airCareIntent.  Expecting 'Cabin_Air_Care_Supervisor.AirCareIntent_Payload' but received ${v}")
      case _ => None[Cabin_Air_Care_Supervisor.AirCareIntent.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_airCareIntent_payload(): Option[Cabin_Air_Care_Supervisor.AirCareIntent_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.CabinAirCareSupervisor_Instance_airCareSupervisionProcess_preferenceInterpreter.initialization_api.airCareIntent_Id).asInstanceOf[Option[Cabin_Air_Care_Supervisor.AirCareIntent_Payload]]
  }

